// R1-D-2(a) step: after native FixUp (phase 1), native routing rules also re-normalise connectors that E2a-core
// does not touch. Restore the R1 edgePoints of every preserved connector whose R1 route does NOT pass through a
// new block shape (pure normalisation churn). Connectors whose R1 route crosses a new shape keep the native reroute
// (otherwise the old line would run through the new block) and are reported as the only R1-D-2(a) exceptions.
// Shapes, model, SAL and SGVL are copied unchanged; CRC is regenerated by a second native save (-NoFixUp).
// node restore-routes.mjs <r1Dir> <phase1Dir> <outDir> <report.json>
import fs from 'node:fs';
import path from 'node:path';
import {parse, walk, anc, applyEdits} from './xmlpos.mjs';
const [r1Dir, p1Dir, outDir, rep] = process.argv.slice(2);
const DIA = 'TwinSafeGroup1.sal.diagram';
const a = fs.readFileSync(path.join(r1Dir, DIA), 'utf8'), b = fs.readFileSync(path.join(p1Dir, DIA), 'utf8');
const A = walk(parse(a)), B = walk(parse(b));
const ids = new Set(A.filter(n => n.attr.Id).map(n => n.attr.Id));
const newBoxes = B.filter(n => /^fB\w+Shape$/.test(n.tag) && !ids.has(n.attr.Id)).map(n => ({block: n.children[0].attr.name, box: n.attr.absoluteBounds.split(',').map(Number)}));
const pts = s => [...s.matchAll(/\(([-\d.]+) : ([-\d.]+)/g)].map(m => [+m[1], +m[2]]);
const segHits = ([x1, y1], [x2, y2], [bx, by, bw, bh]) => {const m = 0.2; // include port stubs left/right of the box
  const L = bx - m, R = bx + bw + m, T = by, Bt = by + bh;
  if (y1 === y2) return y1 >= T && y1 <= Bt && Math.max(x1, x2) >= L && Math.min(x1, x2) <= R;
  if (x1 === x2) return x1 >= L && x1 <= R && Math.max(y1, y2) >= T && Math.min(y1, y2) <= Bt;
  return false;};
const ca = new Map(A.filter(n => n.tag === 'wiredLinkConnector').map(n => [n.attr.Id, n]));
const edits = [], restored = [], keptNative = [];
for (const c of B.filter(n => n.tag === 'wiredLinkConnector')) {
  const o = ca.get(c.attr.Id); if (!o || o.attr.edgePoints === c.attr.edgePoints) continue;
  const p = pts(o.attr.edgePoints);
  const hit = newBoxes.filter(nb => p.some((q, i) => i && segHits(p[i - 1], q, nb.box))).map(nb => nb.block);
  if (hit.length) {keptNative.push({id: c.attr.Id, crosses: hit, r1: o.attr.edgePoints, native: c.attr.edgePoints}); continue;}
  const open = b.slice(c.start, c.openEnd); const old = `edgePoints="${c.attr.edgePoints}"`; if (open.split(old).length !== 2) throw Error('edgePoints not unique ' + c.attr.Id);
  // only the edgePoints attribute is restored; other connector attributes must already be equal
  const strip = n => JSON.stringify(Object.fromEntries(Object.entries(n.attr).filter(([k]) => k !== 'edgePoints')));
  if (strip(o) !== strip(c)) throw Error('connector attrs differ ' + c.attr.Id);
  edits.push([c.start, c.openEnd, open.replace(old, `edgePoints="${o.attr.edgePoints}"`)]);
  restored.push(c.attr.Id);
}
fs.mkdirSync(outDir, {recursive: true});
fs.writeFileSync(path.join(outDir, DIA), applyEdits(b, edits));
for (const f of ['TwinSafeGroup1.sal', 'GVL1.sgvl']) fs.copyFileSync(path.join(p1Dir, f), path.join(outDir, f));
fs.writeFileSync(rep, JSON.stringify({newBoxes, restored: restored.length, restoredIds: restored, keptNative}, null, 1) + '\n');
console.log(JSON.stringify({restored: restored.length, keptNative: keptNative.map(k => k.id + ' crosses ' + k.crosses)}));
